#!/usr/bin/env node
// Compile a ".mw" source into ABC.
// A .mw file is ABC in every respect except one: in music lines every pitch is written as it
// SOUNDS. "^f" is F sharp, "_b" is B flat and a bare letter is always natural, whatever the
// key signature or earlier accidentals in the bar. This removes key-signature/bar-state mistakes.
// The compiler writes the minimal accidentals standard notation needs (per octave, reset at
// each bar line), which is also how abcjs propagates accidentals (verified in tools/selftest.js).
// usage: node compile.js in.mw out.abc
const fs = require('fs');
const [, , inFile, outFile] = process.argv;
const src = fs.readFileSync(inFile, 'utf8');

const SHARPS = ['F', 'C', 'G', 'D', 'A', 'E', 'B'], FLATS = ['B', 'E', 'A', 'D', 'G', 'C', 'F'];
const MAJOR = { C: 0, G: 1, D: 2, A: 3, E: 4, B: 5, 'F#': 6, 'C#': 7, F: -1, Bb: -2, Eb: -3, Ab: -4, Db: -5, Gb: -6, Cb: -7 };
function keySig(k) {
  const m = /^([A-G][#b]?)\s*(m|min|minor|maj|major)?/.exec(k.trim());
  if (!m) throw new Error('bad key ' + k);
  let n = MAJOR[m[1]];
  if (m[2] && m[2][0] === 'm' && m[2] !== 'maj' && m[2] !== 'major') n -= 3;
  const sig = {};
  if (n > 0) SHARPS.slice(0, n).forEach(l => sig[l] = 1);
  if (n < 0) FLATS.slice(0, -n).forEach(l => sig[l] = -1);
  return sig;
}

let sig = {};
const out = [];
const state = {};          // voice -> { "F5": alteration } for the current bar
for (const line of src.split('\n')) {
  const k = /^K:\s*(.*)$/.exec(line);
  if (k) { sig = keySig(k[1]); out.push(line); continue; }
  const m = /^\[V:\s*(\S+)\]/.exec(line);
  if (!m) { out.push(line); continue; }
  const v = m[1];
  if (!state[v]) state[v] = {};
  let bar = state[v];
  let res = m[0], i = m[0].length;
  const s = line;
  while (i < s.length) {
    const c = s[i];
    if (c === '%') { res += s.slice(i); break; }
    if (c === '"') { const j = s.indexOf('"', i + 1); res += s.slice(i, j + 1); i = j + 1; continue; }
    if (c === '!') { const j = s.indexOf('!', i + 1); res += s.slice(i, j + 1); i = j + 1; continue; }
    if (c === '[' && /^\[[A-Za-z]:/.test(s.slice(i))) { const j = s.indexOf(']', i); res += s.slice(i, j + 1); i = j + 1; continue; }
    if (c === '|' || (c === ':' && s[i + 1] === '|') || (c === '[' && s[i + 1] === '|')) {
      // any bar line resets accidentals
      let j = i; while (j < s.length && /[|:\]\[]/.test(s[j]) && !(s[j] === '[' && j > i && /[A-Ga-g^_=z]/.test(s[j + 1] || ''))) j++;
      res += s.slice(i, j); i = j; bar = state[v] = {}; continue;
    }
    const n = /^([\^_=]*)([A-Ga-g])([,']*)/.exec(s.slice(i));
    if (n) {
      const [tok, acc, letter, oct] = n;
      if (acc.includes('=')) throw new Error(`"=" is not used in .mw sources (bare letter is natural): ${line}`);
      const want = acc === '' ? 0 : acc === '^' ? 1 : acc === '_' ? -1 : acc === '^^' ? 2 : acc === '__' ? -2 : NaN;
      if (Number.isNaN(want)) throw new Error('bad accidental ' + tok);
      const up = letter.toUpperCase();
      const key = up + (letter === up ? 4 : 5) + oct;
      const cur = key in bar ? bar[key] : (sig[up] || 0);
      let a = '';
      if (cur !== want) { a = want === 0 ? '=' : acc; bar[key] = want; }
      res += a + letter + oct; i += tok.length; continue;
    }
    res += c; i++;
  }
  out.push(res);
}
fs.writeFileSync(outFile, out.join('\n'));

