#!/usr/bin/env node
// Counterpoint and notation checks for a violin + keyboard (RH, LH) score in ABC.
// Evidence, not proof of good music. It reads the notes exactly as abcjs will play them.
// usage: node check.js file.abc [--grid] [--bars a-b] [--quiet-info]
const ABCJS = require('[local path removed]');
const fs = require('fs');
const args = process.argv.slice(2);
const file = args[0];
const has = k => args.includes(k);
const opt = k => { const i = args.indexOf(k); return i < 0 ? null : args[i + 1]; };
const barsOpt = opt('--bars');
const [barFrom, barTo] = barsOpt ? barsOpt.split('-').map(Number) : [-1, 1e9];
const raw = fs.readFileSync(file, 'utf8');
const VOICES = ['Vn', 'RH', 'LH'];
const LOW = [55, 55, 36], HIGH = [88, 86, 67];
const NAMES = ['C', 'C#', 'D', 'D#', 'E', 'F', 'F#', 'G', 'G#', 'A', 'A#', 'B'];
const nn = p => NAMES[p % 12] + (Math.floor(p / 12) - 1);
const T = 192;                               // ticks per whole note
const issues = [];
const add = (sev, bar, beat, msg) => issues.push({ sev, bar, beat, msg });

// ---------- 1. parser warnings and bar lengths ----------
const clean = raw.replace(/^%%(label|note)\b.*$/gm, '%');
const tune = ABCJS.parseOnly(clean)[0];
(tune.warnings || []).forEach(w => add('ERROR', 0, 0, 'parser: ' + w.replace(/<[^>]+>/g, '')));
const meter = tune.getMeterFraction();
const barLen = meter.num / meter.den;
const compound = meter.den === 8 && meter.num % 3 === 0;
const beatLen = compound ? 3 / 8 : 1 / meter.den;
const perVoice = {};
tune.lines.forEach(line => (line.staff || []).forEach((st, si) => st.voices.forEach((v, vi) => {
  const key = si + '.' + vi; (perVoice[key] = perVoice[key] || []).push(...v);
})));
const barCounts = []; let pickup = 0;
Object.keys(perVoice).forEach((key, idx) => {
  let acc = 0, bar = 1, tuplet = null; const partial = [];
  for (const el of perVoice[key]) {
    if (el.el_type === 'note') {
      let d = el.duration;
      if (el.startTriplet) tuplet = { mult: el.tripletMultiplier, left: el.tripletR || el.startTriplet };
      if (tuplet) { d *= tuplet.mult; if (--tuplet.left <= 0) tuplet = null; }
      acc += d;
    } else if (el.el_type === 'bar') {
      if (acc > 0) { if (Math.abs(acc - barLen) > 1e-6) partial.push([bar, acc]); bar++; acc = 0; }
    }
  }
  if (acc > 0) { partial.push([bar, acc]); bar++; }
  barCounts.push(bar - 1);
  // a pickup and the bars around a mid-movement repeat may be partial if they pair up
  partial.forEach(([b, a], i) => {
    if (b === 1 && a < barLen) { if (idx === 0) pickup = a; return; }
    const nxt = partial[i + 1], prv = partial[i - 1];
    if (nxt && nxt[0] === b + 1 && Math.abs(a + nxt[1] - barLen) < 1e-6) return;
    if (prv && prv[0] === b - 1 && Math.abs(a + prv[1] - barLen) < 1e-6) return;
    if (i === partial.length - 1 && Math.abs(a + pickup - barLen) < 1e-6) return;   // last bar completes the pickup
    add('ERROR', b, 0, `${VOICES[idx] || key}: written bar ${b} has ${a * 16} sixteenths, expected ${barLen * 16}`);
  });
});
if (new Set(barCounts).size > 1) add('ERROR', 0, 0, 'voices have different bar counts: ' + barCounts.join(', '));

// ---------- 2. notes as played (repeats, ornaments and tempo changes removed) ----------
const flat = clean.replace(/\[Q:[^\]]*\]/g, m => ' '.repeat(m.length))
  .replace(/!(trill|mordent|uppermordent|lowermordent|turn|fermata|pralltriller)!/g, m => ' '.repeat(m.length))
  .replace(/\{[^}]*\}/g, m => ' '.repeat(m.length))
  .replace(/\|:/g, '| ').replace(/:\|/g, ' |').replace(/::/g, '| ');
const seq = ABCJS.parseOnly(flat)[0].setUpAudio();
const LET = { C: 0, D: 2, E: 4, F: 5, G: 7, A: 9, B: 11 }, LI = 'CDEFGAB';
function spell(ev) {            // diatonic step number and alteration, from the source text
  const text = flat.slice(ev.startChar, ev.endChar).replace(/![^!]*!/g, '').replace(/"[^"]*"/g, '');
  const re = /[\^_=]*([A-Ga-g])([,']*)/g; let m, best = null;
  while ((m = re.exec(text))) {
    const up = m[1].toUpperCase();
    let o = (m[1] === up ? 4 : 5); for (const ch of m[2]) o += ch === "'" ? 1 : -1;
    const nat = 12 * (o + 1) + LET[up], alt = ev.pitch - nat;
    if (Math.abs(alt) <= 2 && (!best || Math.abs(alt) < Math.abs(best.alt))) best = { step: 7 * o + LI.indexOf(up), alt, letter: up };
  }
  return best || { step: null, alt: 0, letter: '?' };
}
const tracks = seq.tracks.map(t => t.filter(e => e.cmd === 'note').map(e => {
  const sp = spell(e);
  return { p: e.pitch, s: Math.round(e.start * T), e: Math.round((e.start + e.duration) * T), step: sp.step, alt: sp.alt, letter: sp.letter };
}));
// a line per voice: for chords keep the top note in the upper staves, the bottom in the bass
const lines = tracks.map((t, vi) => {
  const by = new Map();
  t.forEach(n => { const k = n.s; if (!by.has(k)) by.set(k, []); by.get(k).push(n); });
  const out = [];
  [...by.keys()].sort((a, b) => a - b).forEach(k => {
    const g = by.get(k).sort((a, b) => a.p - b.p);
    const main = vi === tracks.length - 1 ? g[0] : g[g.length - 1];
    main.chord = g; out.push(main);
  });
  out.forEach((n, i) => { n.i = i; n.v = vi; });
  return out;
});
const BL = Math.round(barLen * T), BT = Math.round(beatLen * T), PU = Math.round(pickup * T);
const off = PU ? BL - PU : 0;
const barOf = t => Math.floor((t + off) / BL) + (PU ? 0 : 1);
const posIn = t => (t + off) % BL;
const beatOf = t => +(posIn(t) / BT + 1).toFixed(2);
const strength = t => { const p = posIn(t); if (p % BT === 0) return 2; const sub = compound ? BT / 3 : BT / 2; return p % sub === 0 ? 1 : 0; };
const where = t => `b${barOf(t)}:${beatOf(t)}`;
const total = Math.max(...lines.map(l => l.length ? l[l.length - 1].e : 0));
const tempoM = /^Q:.*?(\d+)\/(\d+)\s*=\s*(\d+)/m.exec(raw);
const secPerWhole = tempoM ? 60 / (+tempoM[3]) / (+tempoM[1] / +tempoM[2]) : 2;

// ---------- 3. ranges, long notes, melodic intervals ----------
lines.forEach((l, vi) => l.forEach((n, i) => {
  n.chord.forEach(c => { if (c.p < LOW[vi] || c.p > HIGH[vi]) add('ERROR', barOf(n.s), beatOf(n.s), `${VOICES[vi]} ${nn(c.p)} out of range`); });
  const secs = (n.e - n.s) / T * secPerWhole;
  if (vi === 0 && secs > 5) add('WARN', barOf(n.s), beatOf(n.s), `Vn ${nn(n.p)} lasts ${secs.toFixed(1)} s (sample sustain limit about 6 s)`);
  const nx = l[i + 1];
  if (!nx || nx.s - n.e > BT) return;
  const semi = nx.p - n.p, dia = (nx.step != null && n.step != null) ? nx.step - n.step : null, a = Math.abs(semi);
  const at = `${VOICES[vi]} ${nn(n.p)}→${nn(nx.p)}`;
  if (a > 12) add('WARN', barOf(nx.s), beatOf(nx.s), `${at} leap larger than an octave`);
  else if (dia != null && Math.abs(dia) === 1 && a === 3) add('WARN', barOf(nx.s), beatOf(nx.s), `${at} augmented second`);
  else if (a === 6) add('INFO', barOf(nx.s), beatOf(nx.s), `${at} tritone leap`);
  else if (a === 10 || a === 11) add('INFO', barOf(nx.s), beatOf(nx.s), `${at} seventh leap`);
  else if (dia != null && ((Math.abs(dia) === 3 && a === 4) || (Math.abs(dia) === 2 && a === 2) || (Math.abs(dia) === 4 && a === 8))) add('INFO', barOf(nx.s), beatOf(nx.s), `${at} diminished/augmented leap`);
}));

// ---------- 4. slices ----------
const cuts = new Set([0, total]);
lines.forEach(l => l.forEach(n => { cuts.add(n.s); cuts.add(n.e); }));
const times = [...cuts].sort((a, b) => a - b);
const ptr = lines.map(() => 0);
const slices = [];
for (let k = 0; k < times.length - 1; k++) {
  const t = times[k];
  const snd = lines.map((l, vi) => { while (ptr[vi] < l.length && l[ptr[vi]].e <= t) ptr[vi]++; const n = l[ptr[vi]]; return n && n.s <= t ? n : null; });
  slices.push({ t, end: times[k + 1], snd });
}

// ---------- 5. parallels ----------
for (let a = 0; a < lines.length; a++) for (let b = a + 1; b < lines.length; b++) {
  let prev = null;
  for (const sl of slices) {
    const x = sl.snd[a], y = sl.snd[b];
    if (!x || !y) { prev = null; continue; }
    if (prev && (prev.x !== x || prev.y !== y)) {
      if (prev.x !== x && prev.y !== y && prev.x.p !== x.p && prev.y.p !== y.p) {
        const i1 = Math.abs(prev.x.p - prev.y.p) % 12, i2 = Math.abs(x.p - y.p) % 12;
        const same = Math.sign(x.p - prev.x.p) === Math.sign(y.p - prev.y.p);
        if (i1 === i2 && (i1 === 0 || i1 === 7)) {
          const kind = i1 === 7 ? 'fifths' : (prev.x.p === prev.y.p ? 'unisons' : 'octaves');
          add(same ? 'ERROR' : 'WARN', barOf(sl.t), beatOf(sl.t), `${same ? 'parallel' : 'contrary-motion'} ${kind} ${VOICES[a]}/${VOICES[b]}: ${nn(prev.x.p)}-${nn(prev.y.p)} → ${nn(x.p)}-${nn(y.p)}`);
        } else if (same && (i2 === 0 || i2 === 7) && ((a === 0 || a === 1) && b === 2) && Math.abs(Math.max(x.p, y.p) === x.p ? x.p - prev.x.p : y.p - prev.y.p) > 2 && strength(sl.t) === 2) {
          add('INFO', barOf(sl.t), beatOf(sl.t), `direct ${i2 === 7 ? 'fifth' : 'octave'} ${VOICES[a]}/${VOICES[b]} (upper voice leaps): → ${nn(x.p)}-${nn(y.p)}`);
        }
      }
    }
    prev = { x, y };
  }
