content:
// Render every movement in the real player (headless Chrome) and measure the synthesised audio buffers.
// This inspects audio buffers; it is not listening.
// usage: node render.cjs <url of work.html?...> [--solo]
const { launch } = require('repo/tests/browser.cjs');
const url = process.argv[2];
const solo = process.argv.includes('--solo');
const sleep = ms => new Promise(r => setTimeout(r, ms));
async function waitFor(page, expr, ms = 120000, step = 300) {
  const end = Date.now() + ms; let v;
  while (Date.now() < end) { v = await page.eval(expr); if (v) return v; await sleep(step); }
  return v;
}
const STATS = `(() => { const s = mwPlayer.synth(); const b = s && s.midiBuffer && s.midiBuffer.audioBuffers && s.midiBuffer.audioBuffers[0]; if (!b) return null;
  const sr = b.sampleRate, n = b.length, win = Math.floor(sr * 1); const L = b.getChannelData(0), R = b.numberOfChannels > 1 ? b.getChannelData(1) : L;
  let pk = 0, sum = 0; const rms = [];
  for (let w = 0; w * win < n; w++) { let a = 0, c = 0; for (let i = w * win; i < Math.min(n, (w + 1) * win); i++) { const x = (L[i] + R[i]) / 2; a += x * x; c++; const m = Math.max(Math.abs(L[i]), Math.abs(R[i])); if (m > pk) pk = m; } sum += a; rms.push(Math.sqrt(a / c)); }
  const body = rms.slice(0, Math.max(1, rms.length - 3));
  return { seconds: +b.duration.toFixed(1), peak: +pk.toFixed(3), rms: +Math.sqrt(sum / n).toFixed(4), minWindow: +Math.min(...body).toFixed(4), quietSeconds: body.map((v, i) => v < 0.004 ? i : -1).filter(i => i >= 0),
    warn: document.getElementById('pl-warn').textContent, clock: document.getElementById('pl-clock').textContent, svg: document.querySelectorAll('#pl-paper svg').length,
    parts: mwPlayer.parts().map(p => p.label + ':' + p.program + (p.on ? '' : '(off)')) }; })()`;
(async () => {
  const page = await launch({ width: 1280, height: 1000, port: 9377 });
  try {
    await page.send('Page.navigate', { url });
    await waitFor(page, "document.readyState === 'complete' && !!window.mwPlayer && !!document.querySelector('#pl-paper svg')", 40000);
    const title = await page.eval("document.getElementById('pl-title').textContent");
    const moves = await page.eval("[...document.querySelectorAll('#pl-movements button')].map(b => b.textContent.trim().slice(0, 40))");
    console.log('title:', title, '| movements:', JSON.stringify(moves));
    for (let i = 0; i < moves.length; i++) {
      await page.eval(`document.querySelectorAll('#pl-movements button')[${i}].click()`);
      await sleep(1500);
      await waitFor(page, "!!document.querySelector('#pl-paper svg') && !document.getElementById('pl-play').disabled", 30000);
      const modes = solo ? ['all', 0, 1, 2] : ['all'];
      for (const mode of modes) {
        const nparts = await page.eval("document.querySelectorAll('#pl-parts button').length");
        for (let k = 0; k < nparts; k++) {
          const want = mode === 'all' || mode === k;
          const on = await page.eval(`document.querySelectorAll('#pl-parts button')[${k}].getAttribute('aria-pressed') === 'true'`);
          if (on !== want) { await page.eval(`document.querySelectorAll('#pl-parts button')[${k}].click()`); await sleep(150); }
        }
        await page.eval("document.getElementById('pl-play').click()");
        const ok = await waitFor(page, "mwPlayer.state() === 'playing' || !document.getElementById('pl-error').hidden", 180000);
        const err = await page.eval("document.getElementById('pl-error').hidden ? '' : document.getElementById('pl-error').textContent");
        await sleep(400);
        const st = await page.eval(STATS);
        console.log(`movement ${i + 1} [${mode === 'all' ? 'all parts' : 'solo part ' + (mode + 1)}]`, ok ? '' : 'NOT PLAYING', err, JSON.stringify(st));
        await page.eval("mwPlayer.stop()"); await sleep(500);
      }
    }
    const bad = page.logs.filter(l => /EXCEPTION|error/i.test(l)).slice(0, 8);
    console.log('console problems:', JSON.stringify(bad));
  } finally { await page.close(); }
})().catch(e => { console.error('FAILED', e); process.exit(1); });

